import{_ as t,c as s,o as i,j as e,a as r}from"./chunks/framework.Dnh4IO1K.js";const f=JSON.parse('{"title":"卷五·16","description":"易小帖 - 卷五·16","frontmatter":{"title":"卷五·16","description":"易小帖 - 卷五·16"},"headers":[],"relativePath":"classics/yixiaotie/138.md","filePath":"classics/yixiaotie/138.md"}'),o={name:"classics/yixiaotie/138.md"};function c(n,a,l,d,p,m){return i(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"卷五·16",tabindex:"-1"},[r("卷五·16 "),e("a",{class:"header-anchor",href:"#卷五·16","aria-label":"Permalink to “卷五·16”"},"​")],-1),e("p",null,"答：某謂易配五行不合者，以卦義言，則離為火，坎為水，巽為木似矣。然而震不為木，兌不為金，即乾之為金，不過與為玉並言，非五行之金也。若坤則又不為土而為地，艮則又不為土而為山，則其於五者不詳不備，不合一也。以卦位言，則震木兌金離火坎水似矣，然而坤不是火，艮不是水，有四正而無四維，即曰坤艮是土，正合五行，然何以水火各一卦，而金木與土則各有複卦，且何以中央之土，反無卦位，二不合也。以卦數言，則天一為坎，地二為離，天三為震，地四為兌，而乾巽艮坤則又以六七八九，就天地而分屬之似矣。然而土為五十，反為卦數所不取。夫三五至精，五行之數，全在正五。今卦有合五而無正五，如金水為一五，木火為一五，皆可兩合，而土之正五卦反不及，三不合也。況僕作是說，亦自有為言之。謂太極圖說專論五行，且欲以五行生八卦，則世無此理。故言之頗斷，至於五行八卦，本不相礙，且亦彼此有根據處。至京焦之易，則直以五行為主，而撇卦辭卦義卦象於不問，此雖非三聖之易，然其不相礙而可相通，固有然也。",-1)])])}const x=t(o,[["render",c]]);export{f as __pageData,x as default};
